import {calendarLetters} from './calendar-state.js';
const places={paris:'巴黎 · 街角的早餐',kyoto:'京都 · 樱花树下',cairo:'开罗 · 沙漠漫游',venice:'威尼斯 · 水上的风'};
export const travelImage=p=>'assets/travel/'+p.destination+'-'+(p.avatar===0?'white':'brown')+'.png';
export function createTravelUI({cloud,context,modal,close,handlers,toast,onDepart,words}){
 let data=null,busy=false,index=0,version=0,mailOpen=false,mailSignature='';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const letters=()=>{const s=context();return calendarLetters(s.state.notes,s.date,s.actor,s.paired)};
 const readKey=()=> 'echoo-calendar-mail-'+(cloud?.session.accountId??context().actor);
 let read={};try{read=JSON.parse(localStorage.getItem(readKey())||'{}')||{}}catch{}
 function unreadLetters(){const s=context();return letters().filter(n=>read.date!==s.date||!read.ids?.includes(n.id))}
 function markLetters(){read={date:context().date,ids:letters().map(n=>n.id)};try{localStorage.setItem(readKey(),JSON.stringify(read))}catch{}}
 const badge=document.createElement('button');badge.className='travel-badge';badge.hidden=true;badge.onclick=mailbox;document.querySelector('.scene-wrap').append(badge);
 const album=document.createElement('dialog');album.id='travel-album';album.setAttribute('aria-label','旅行相册');document.body.append(album);
 function paint(){const s=context(),count=(data?.unread||0)+unreadLetters().length;s.visual?.travelAway(!!data?.away);s.visual?.mailFlag(count>0&&s.world===s.actor);badge.hidden=s.world!==s.actor||(!data?.away&&!count);badge.textContent=count?'✉ '+count+' 封来信':data?.away?'旅行中 · 信箱':'';const sig=JSON.stringify(letters());if(mailOpen&&document.querySelector('#panel')?.open&&document.querySelector('#panel')?.dataset.page==='travel-mail'&&sig!==mailSignature)drawMail();}
 async function api(action){if(!cloud)throw Error('请在服务器版本中开启旅行');const r=await fetch('/api/travel',{method:action?'POST':'GET',headers:action?{'Content-Type':'application/json','X-CSRF-Token':cloud.session.csrf,'X-Planet-Space':String(cloud.session.space)}:{},body:action?JSON.stringify({action}):undefined});const result=await r.json();if(!r.ok)throw Error(result.error||'暂时连接不上');return result}
 async function load(){if(busy||!cloud)return;const seq=++version;try{const next=await api();if(seq!==version)return;const returned=data?.away&&!next.away,departed=next.away&&!data?.away;data=next;if(departed)onDepart();paint();if(returned)toast('小熊回来了')}catch{}}
 function suitcase(){if(context().world!==context().actor){toast('这是对方的旅行箱');return}modal('travel','Echoo','出去走走','<div class="travel-start"><span aria-hidden="true">✧</span><p>'+(data?.away?'小熊正在旅行。':'带上旅行箱，去看看远方。')+'</p><small>旅途中会寄回照片，最晚明天回来。</small>'+(data?.away?'':'<button class="pill primary" data-do="travel-depart">出发</button>')+'</div>')}
 async function depart(){if(busy)return;busy=true;version++;try{if(cloud&&!(await cloud.flush()))return;data=await api('depart');close();onDepart();paint();toast('出发了，等一封远方的来信')}catch(e){toast(e.message)}finally{busy=false}}
 function drawMail(){const notes=letters(),incoming=data?.photos.filter(p=>!p.seen)||[];mailSignature=JSON.stringify(notes);modal('travel-mail','','信箱',(notes.length?'<div class="calendar-notes">'+notes.map(n=>'<article><small>'+(n.anniversary?'今天的纪念日':'今天的记事')+'</small><h3>'+esc(n.title)+'</h3>'+(n.body?'<p>'+esc(n.body)+'</p>':'')+'</article>').join('')+'</div><button class="pill" data-do="calendar">查看日历</button>':'')+(incoming.length?'<div class="travel-letters">'+incoming.map(p=>'<figure><img src="'+travelImage(p)+'" alt="'+places[p.destination]+'"><figcaption>'+places[p.destination]+'</figcaption></figure>').join('')+'</div><button class="pill primary" data-do="travel-collect">收进相册</button>':notes.length?'':'<p class="subtle">暂时没有新来信。</p>'));}
 async function mailbox(){if(context().world!==context().actor){toast('这是对方的信箱');return}await load();mailOpen=true;drawMail();markLetters();paint()}
 async function collect(){if(busy)return;busy=true;version++;try{data=await api('collect');paint();close();toast('照片已收进相册')}catch(e){toast(e.message)}finally{busy=false}}
 function stopAlbum(){if(!album.open)return;album.close();context().visual?.album(false)}
 function drawAlbum(turn=false){const photos=data?.photos.filter(p=>p.seen)||[];index=Math.max(0,Math.min(index,photos.length-1));const p=photos[index];album.innerHTML='<header><span>旅行相册</span><button data-album="close" aria-label="合上相册">×</button></header>'+(p?'<img src="'+travelImage(p)+'" alt="'+places[p.destination]+'"><footer><button data-album="prev" aria-label="上一张" '+(index===0?'disabled':'')+'>‹</button><span>'+places[p.destination]+'<small>'+ (index+1)+' / '+photos.length+'</small></span><button data-album="next" aria-label="下一张" '+(index===photos.length-1?'disabled':'')+'>›</button></footer>':'<p class="subtle">照片会从远方寄来。</p>');context().visual?.album(true,p?travelImage(p):null,turn)}
 async function openAlbum(){await load();if(data?.away)return toast('等小熊回来，再一起翻相册');close();if(!album.open)album.show();drawAlbum()}
 function sofa(seat){context().visual?.sofaStudy(true,seat);modal('sofa','Echoo','坐一会儿','<div class="sofa-options"><button data-do="sofa-words"><span>▤</span>背单词</button><button data-do="sofa-album"><span>▧</span>看相册</button></div>')}
 album.onclick=e=>{const a=e.target.closest('[data-album]')?.dataset.album;if(a==='close')stopAlbum();if(a==='next'||a==='prev'){index+=a==='next'?1:-1;drawAlbum(true)}};album.addEventListener('cancel',e=>{e.preventDefault();stopAlbum()});let startX=0;album.onpointerdown=e=>startX=e.clientX;album.onpointerup=e=>{if(Math.abs(e.clientX-startX)>50){index+=e.clientX<startX?1:-1;drawAlbum(true)}};
 handlers['travel-depart']=depart;handlers['travel-collect']=collect;handlers['sofa-words']=()=>{close();words()};handlers['sofa-album']=openAlbum;
 setInterval(()=>{if(!document.hidden)paint()},1000);setInterval(()=>{if(!document.hidden)load()},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)load()});load();
 return {suitcase,mailbox,sofa,paint,load,stopAlbum,get away(){return !!data?.away}};
}
